/*
 * GEMINI ✦ MARK REMOVER (2026-10-27)
 * ----------------------------------
 * Gemini puts a small white ✦ sparkle in the bottom-right corner of the
 * photos it makes. It is a see-through white shape painted on top of the
 * photo ("alpha blending"), so the exact original pixels can be worked
 * back out with maths - nothing is guessed or redrawn by AI:
 *
 *      original = (photo - alpha * 255) / (1 - alpha)
 *
 * How it decides (all inside the browser, nothing is sent anywhere):
 *   1. Looks for the ✦ shape in the bottom-right corner (exact Gemini
 *      positions first, then a wider search for photos that were
 *      resized / cropped a little).
 *   2. Tries different strengths of removal and keeps the one that leaves
 *      the corner smoothest. If "no removal" is the smoothest, the photo
 *      has no ✦ and is returned UNCHANGED.
 * So normal bag photos (Meesho etc.) are never touched.
 *
 * Only the visible ✦ is handled. Gemini's invisible SynthID mark stays.
 *
 * The ✦ shape maps (alpha maps) come from GeminiWatermarkTool by AllenK
 * (Kwyshell), MIT License - https://github.com/allenk/GeminiWatermarkTool
 */

const MAPS_RAW = {
  v1s: { size: 48, b64: "" },
  v1l: { size: 96, b64: "" },
  v2s: { size: 36, b64: "" },
  v2l: { size: 96, b64: "" },
};

let mapsCache = null;
function getMaps() {
  if (mapsCache) return mapsCache;
  mapsCache = {};
  for (const [key, { size, b64 }] of Object.entries(MAPS_RAW)) {
    const bin = atob(b64);
    const alpha = new Float32Array(size * size);
    for (let i = 0; i < bin.length; i++) alpha[i] = bin.charCodeAt(i) / 255;
    mapsCache[key] = { size, alpha };
  }
  return mapsCache;
}

// Bilinear resize of a square alpha map to `target` px.
const resizedCache = new Map();
function getMap(key, target) {
  const id = `${key}:${target}`;
  if (resizedCache.has(id)) return resizedCache.get(id);
  const { size, alpha } = getMaps()[key];
  let out = alpha;
  if (target !== size) {
    out = new Float32Array(target * target);
    const ratio = size / target;
    for (let y = 0; y < target; y++) {
      // area-ish sampling: sample centre of each target pixel
      const sy = Math.min(size - 1, Math.max(0, (y + 0.5) * ratio - 0.5));
      const y0 = Math.floor(sy), y1 = Math.min(size - 1, y0 + 1), fy = sy - y0;
      for (let x = 0; x < target; x++) {
        const sx = Math.min(size - 1, Math.max(0, (x + 0.5) * ratio - 0.5));
        const x0 = Math.floor(sx), x1 = Math.min(size - 1, x0 + 1), fx = sx - x0;
        const a = alpha[y0 * size + x0] * (1 - fx) + alpha[y0 * size + x1] * fx;
        const b = alpha[y1 * size + x0] * (1 - fx) + alpha[y1 * size + x1] * fx;
        out[y * target + x] = a * (1 - fy) + b * fy;
      }
    }
  }
  const stats = mapStats(out);
  let peak = 0;
  for (let i = 0; i < out.length; i++) if (out[i] > peak) peak = out[i];
  const { gx, gy } = gradients(out, target, target);
  const sx = mapStats(gx), sy = mapStats(gy);
  const entry = {
    size: target, alpha: out, peak, ...stats,
    gx, gxMean: sx.mean, gxNorm: sx.norm,
    gy, gyMean: sy.mean, gyNorm: sy.norm,
  };
  resizedCache.set(id, entry);
  return entry;
}

function mapStats(alpha) {
  let sum = 0;
  for (let i = 0; i < alpha.length; i++) sum += alpha[i];
  const mean = sum / alpha.length;
  let ss = 0;
  for (let i = 0; i < alpha.length; i++) ss += (alpha[i] - mean) ** 2;
  return { mean, norm: Math.sqrt(ss) };
}

// Grey copy of the image (one float per pixel).
function toGray(data, width, height) {
  const g = new Float32Array(width * height);
  for (let i = 0, p = 0; i < g.length; i++, p += 4) {
    g[i] = (data[p] + data[p + 1] + data[p + 2]) / 3;
  }
  return g;
}

// Gradients (simple central differences) of a grey picture.
function gradients(gray, width, height) {
  const gx = new Float32Array(width * height);
  const gy = new Float32Array(width * height);
  for (let y = 1; y < height - 1; y++) {
    for (let x = 1; x < width - 1; x++) {
      const i = y * width + x;
      gx[i] = gray[i + 1] - gray[i - 1];
      gy[i] = gray[i + width] - gray[i - width];
    }
  }
  return { gx, gy };
}

// Normalised cross-correlation of patch(px,py) of `img` with `tpl`
// (n x n). tplMean/tplNorm precomputed.
function nccArr(img, width, tpl, n, tplMean, tplNorm, px, py) {
  let sum = 0;
  for (let y = 0; y < n; y++) {
    const row = (py + y) * width + px;
    for (let x = 0; x < n; x++) sum += img[row + x];
  }
  const mean = sum / (n * n);
  let num = 0, ss = 0;
  for (let y = 0; y < n; y++) {
    const row = (py + y) * width + px;
    const mrow = y * n;
    for (let x = 0; x < n; x++) {
      const d = img[row + x] - mean;
      num += d * (tpl[mrow + x] - tplMean);
      ss += d * d;
    }
  }
  if (ss < 1e-6 || tplNorm < 1e-6) return 0;
  return num / (Math.sqrt(ss) * tplNorm);
}

// Shape score: half "brightness looks like ✦", half "edges look like ✦".
// Edges matter most on busy backgrounds (walls, clothes, floors).
function ncc(ctx, map, px, py) {
  const n = map.size;
  const a = nccArr(ctx.gray, ctx.W, map.alpha, n, map.mean, map.norm, px, py);
  const gx = nccArr(ctx.gx, ctx.W, map.gx, n, map.gxMean, map.gxNorm, px, py);
  const gy = nccArr(ctx.gy, ctx.W, map.gy, n, map.gyMean, map.gyNorm, px, py);
  return 0.4 * a + 0.3 * gx + 0.3 * gy;
}

// Half-size copy (2x2 average) for the quick wide search.
function halfCtx(ctx) {
  const W = Math.floor(ctx.W / 2), H = Math.floor(ctx.H / 2);
  const gray = new Float32Array(W * H);
  for (let y = 0; y < H; y++) {
    for (let x = 0; x < W; x++) {
      const i = 2 * y * ctx.W + 2 * x;
      gray[y * W + x] = (ctx.gray[i] + ctx.gray[i + 1] + ctx.gray[i + ctx.W] + ctx.gray[i + ctx.W + 1]) / 4;
    }
  }
  const { gx, gy } = gradients(gray, W, H);
  return { gray, gx, gy, W, H };
}

// Exact positions Gemini uses (same rules as GeminiWatermarkTool).
function knownCandidates(W, H) {
  const out = [];
  const large = W > 1024 && H > 1024;
  // V1 (older Gemini)
  if (large) out.push({ key: "v1l", size: 96, mr: 64, mb: 64 });
  else out.push({ key: "v1s", size: 48, mr: 32, mb: 32 });
  // V2 (current Gemini)
  if (large) out.push({ key: "v2l", size: 96, mr: 192, mb: 192 });
  else {
    const long = Math.max(W, H), short = Math.min(W, H);
    let src;
    if (long > 1100) {
      const d = 2 * long;
      src = [2752, 2816, 2848].reduce((a, b) => (Math.abs(d - b) < Math.abs(d - a) ? b : a));
    } else if (short >= 566) src = 2752;
    else if (short >= 550) src = 2816;
    else src = 2848;
    const scale = long / src;
    const margin = Math.round(192 * scale);
    const ideal = Math.round(96 * scale);
    const size = ideal <= 40 ? 36 : ideal;
    out.push({ key: size <= 40 ? "v2s" : "v2l", size, mr: margin, mb: margin });
  }
  // Big Gemini photos that our server already shrank to 2000px (photos
  // already on the website): same spot, just scaled down.
  const long = Math.max(W, H);
  if (long >= 1990 && long <= 2000) {
    for (const src of [2752, 2816, 2848]) {
      const scale = long / src;
      if (scale >= 1) continue;
      const size = Math.round(96 * scale);
      const margin = Math.round(192 * scale);
      out.push({ key: "v2l", size, mr: margin, mb: margin });
    }
  }
  return out;
}

function bestNear(ctx, key, size, cx, cy, radius, stride = 1) {
  const { W, H } = ctx;
  const map = getMap(key, size);
  let best = { score: -1 };
  for (let dy = -radius; dy <= radius; dy += stride) {
    for (let dx = -radius; dx <= radius; dx += stride) {
      const px = cx + dx, py = cy + dy;
      if (px < 0 || py < 0 || px + size > W || py + size > H) continue;
      const s = ncc(ctx, map, px, py);
      if (s > best.score) best = { score: s, key, size, px, py };
    }
  }
  return best;
}

function findMark(ctx, fullW, fullH) {
  const { W, H } = ctx;
  let best = { score: -1 };
  // 1) exact Gemini spots (fast, the usual case)
  for (const c of knownCandidates(fullW, fullH)) {
    const r = bestNear(ctx, c.key, c.size, W - c.mr - c.size, H - c.mb - c.size, 4);
    if (r.score > best.score) best = r;
  }
  const found = [];
  if (best.score >= 0.25) found.push({ ...best, known: true });
  if (best.score >= 0.55) return found;
  best = { score: -1 };

  // 2) wider search (photo resized / cropped a bit). Done on a half-size
  //    copy so it stays quick on a phone, then fine-tuned at full size.
  const long = Math.max(fullW, fullH);
  // The ✦ is always ~3.5-5% of the long side (resizing keeps that).
  const minS = Math.max(16, Math.round(long * 0.025));
  const maxS = Math.min(200, Math.round(long * 0.065));
  const half = halfCtx(ctx);
  let coarse = { score: -1 };
  for (let s = minS; s <= maxS; s = Math.round(s * 1.07) + 1) {
    const size2 = Math.max(10, Math.round(s / 2));
    for (const key of ["v2l"]) {
      const map = getMap(key, size2);
      const reach = Math.round(size2 * 2.6); // furthest margin we look at
      const step = Math.max(1, Math.round(size2 / 10));
      for (let py = half.H - size2 - reach; py <= half.H - size2; py += step) {
        if (py < 0) continue;
        for (let px = half.W - size2 - reach; px <= half.W - size2; px += step) {
          if (px < 0) continue;
          const sc = ncc(half, map, px, py);
          if (sc > coarse.score) coarse = { score: sc, key, size: s, px: px * 2, py: py * 2, step: step * 2 };
        }
      }
    }
  }
  if (coarse.score > 0.3) {
    // fine-tune: rough pass every 2px / 2 sizes, then exact pass
    for (let size = coarse.size - 4; size <= coarse.size + 4; size += 2) {
      if (size < 12) continue;
      const centre = Math.round((coarse.size - size) / 2);
      const r = bestNear(ctx, coarse.key, size, coarse.px + centre, coarse.py + centre, coarse.step + 1, 2);
      if (r.score > best.score) best = r;
    }
    const rough = best;
    for (let size = rough.size - 1; size <= rough.size + 1; size++) {
      if (size < 12 || !rough.size) continue;
      const centre = Math.round((rough.size - size) / 2);
      const r = bestNear(ctx, rough.key, size, rough.px + centre, rough.py + centre, 2);
      if (r.score > best.score) best = r;
    }
  }
  if (best.score >= 0.6) found.push(best);
  return found;
}

// Shape score of the corner AFTER removing with strength `gain`.
// Right strength = the ✦ is gone = score drops to about 0.
function scoreAfter(data, W, map, px, py, gain) {
  const n = map.size;
  const g = new Float32Array(n * n);
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      const a = Math.min(0.99, map.alpha[y * n + x] * gain);
      const p = ((py + y) * W + px + x) * 4;
      const v = (data[p] + data[p + 1] + data[p + 2]) / 3;
      g[y * n + x] = a < 0.002 ? v : (v - a * 255) / (1 - a);
    }
  }
  const { gx, gy } = gradients(g, n, n);
  return ncc({ gray: g, gx, gy, W: n }, map, 0, 0);
}

/**
 * Removes the Gemini ✦ from RGBA pixels IN PLACE.
 * (W,H) = the pixels given (the bottom-right corner of the photo);
 * (fullW,fullH) = the whole photo, used for Gemini's size rules.
 * Returns { removed: boolean, score, gain, box }.
 */
export function removeGeminiMarkFromPixels(data, W, H, fullW = W, fullH = H) {
  if (fullW < 200 || fullH < 200 || W < 60 || H < 60) return { removed: false };
  const gray = toGray(data, W, H);
  const { gx, gy } = gradients(gray, W, H);
  const ctx = { gray, gx, gy, W, H };
  let last = { removed: false };
  for (const hit of findMark(ctx, fullW, fullH)) {
    const result = tryRemove(data, W, hit);
    if (result.removed) return result;
    last = result;
  }
  return last;
}

function tryRemove(data, W, hit) {
  const map = getMap(hit.key, hit.size);
  // Find the strength where the ✦ disappears (score crosses 0).
  let lo = 0, hi = Math.min(2.5, 0.95 / map.peak);
  if (scoreAfter(data, W, map, hit.px, hit.py, hi) > 0) {
    return { removed: false, score: hit.score, gain: hi };
  }
  for (let i = 0; i < 18; i++) {
    const mid = (lo + hi) / 2;
    if (scoreAfter(data, W, map, hit.px, hit.py, mid) > 0) lo = mid;
    else hi = mid;
  }
  const gain = (lo + hi) / 2;
  // A real Gemini ✦ needs about full strength (a bit less if the photo
  // was resized). Anything far from that = not a ✦ -> leave photo alone.
  // (Gemini's ✦ is at most ~37-51% see-through-white at its brightest.)
  const peak = gain * map.peak;
  if (peak < 0.18 || peak > 0.7) return { removed: false, score: hit.score, gain };

  // Fine fit (2026-10-27 v3): photos already on the website were shrunk
  // and re-saved, so the ✦ sits a fraction of a pixel off / slightly
  // smaller. A rough fit leaves a faint "glass" outline. Here position,
  // size and strength are fine-tuned until the ✦ edges disappear.
  const H = Math.floor(data.length / 4 / W);
  const fit = fineFit(data, W, H, hit, gain);
  const finalPeak = fit.gain * fit.peak;
  if (finalPeak < 0.18 || finalPeak > 0.7) return { removed: false, score: hit.score, gain: fit.gain };
  applyFit(data, W, fit);
  cleanEdges(data, W, fit);
  return {
    removed: true,
    score: hit.score,
    gain: fit.gain,
    box: { x: fit.bx, y: fit.by, size: fit.n },
  };
}

// alpha of the ✦ for every pixel of the n x n box. The map's top-left
// sits at (ox, oy) inside the box and each map pixel is `scale` px.
function sampleAlpha(raw, rawSize, scale, ox, oy, n, out) {
  for (let y = 0; y < n; y++) {
    const sy = (y + 0.5 - oy) / scale - 0.5;
    for (let x = 0; x < n; x++) {
      const sx = (x + 0.5 - ox) / scale - 0.5;
      let v = 0;
      if (sx > -1 && sy > -1 && sx < rawSize && sy < rawSize) {
        const x0 = Math.floor(sx), y0 = Math.floor(sy);
        const fx = sx - x0, fy = sy - y0;
        const at = (xx, yy) =>
          xx < 0 || yy < 0 || xx >= rawSize || yy >= rawSize ? 0 : raw[yy * rawSize + xx];
        v = (at(x0, y0) * (1 - fx) + at(x0 + 1, y0) * fx) * (1 - fy) +
            (at(x0, y0 + 1) * (1 - fx) + at(x0 + 1, y0 + 1) * fx) * fy;
      }
      out[y * n + x] = v;
    }
  }
}

function fineFit(data, W, H, hit, gain0) {
  const { alpha: raw, size: rawSize } = getMaps()[hit.key];
  const pad = Math.max(3, Math.round(hit.size * 0.06));
  const bx = Math.max(0, hit.px - pad), by = Math.max(0, hit.py - pad);
  const n = Math.min(hit.size + 2 * pad, W - bx, H - by);
  const gray = new Float32Array(n * n);
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      const p = ((by + y) * W + bx + x) * 4;
      gray[y * n + x] = (data[p] + data[p + 1] + data[p + 2]) / 3;
    }
  }
  const alpha = new Float32Array(n * n);
  const result = new Float32Array(n * n);

  // Where to look: around the ✦ edges (from the first rough fit, widened).
  const start = { scale: hit.size / rawSize, ox: hit.px - bx, oy: hit.py - by, gain: gain0 };
  sampleAlpha(raw, rawSize, start.scale, start.ox, start.oy, n, alpha);
  const edge = new Float32Array(n * n);
  for (let y = 1; y < n - 1; y++) {
    for (let x = 1; x < n - 1; x++) {
      const i = y * n + x;
      edge[i] = Math.abs(alpha[i + 1] - alpha[i - 1]) + Math.abs(alpha[i + n] - alpha[i - n]);
    }
  }
  const weight = new Float32Array(n * n);
  const r = 2;
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      let m = 0;
      for (let dy = -r; dy <= r; dy++) {
        const yy = y + dy;
        if (yy < 0 || yy >= n) continue;
        for (let dx = -r; dx <= r; dx++) {
          const xx = x + dx;
          if (xx < 0 || xx >= n) continue;
          if (edge[yy * n + xx] > m) m = edge[yy * n + xx];
        }
      }
      weight[y * n + x] = m;
    }
  }

  function energy(p) {
    sampleAlpha(raw, rawSize, p.scale, p.ox, p.oy, n, alpha);
    for (let i = 0; i < n * n; i++) {
      const a = Math.min(0.99, alpha[i] * p.gain);
      result[i] = a < 0.002 ? gray[i] : (gray[i] - a * 255) / (1 - a);
    }
    let e = 0;
    for (let y = 1; y < n - 1; y++) {
      for (let x = 1; x < n - 1; x++) {
        const i = y * n + x;
        const w = weight[i];
        if (w < 0.01) continue;
        e += w * (Math.abs(result[i + 1] - result[i - 1]) + Math.abs(result[i + n] - result[i - n]));
      }
    }
    return e;
  }

  let best = { ...start };
  let bestE = energy(best);
  const steps = { scale: start.scale * 0.03, ox: 1, oy: 1, gain: 0.15 };
  for (let round = 0; round < 7; round++) {
    for (const key of ["gain", "ox", "oy", "scale", "gain"]) {
      for (const dir of [1, -1]) {
        let moved = true;
        while (moved) {
          moved = false;
          const trial = { ...best, [key]: best[key] + dir * steps[key] };
          if (trial.gain <= 0) break;
          // never wander far from where the ✦ was found
          if (Math.abs(trial.ox - start.ox) > pad || Math.abs(trial.oy - start.oy) > pad) break;
          if (Math.abs(trial.scale / start.scale - 1) > 0.12) break;
          const e = energy(trial);
          if (e < bestE) { best = trial; bestE = e; moved = true; }
        }
      }
    }
    for (const key of Object.keys(steps)) steps[key] /= 2;
  }
  let peak = 0;
  for (let i = 0; i < raw.length; i++) if (raw[i] > peak) peak = raw[i];
  return { ...best, raw, rawSize, bx, by, n, peak };
}

function applyFit(data, W, fit) {
  const { n } = fit;
  const alpha = new Float32Array(n * n);
  sampleAlpha(fit.raw, fit.rawSize, fit.scale, fit.ox, fit.oy, n, alpha);
  fit.alpha = alpha;
  for (let y = 0; y < n; y++) {
    for (let x = 0; x < n; x++) {
      const a = Math.min(0.99, alpha[y * n + x] * fit.gain);
      if (a < 0.002) continue;
      const p = ((fit.by + y) * W + fit.bx + x) * 4;
      for (let c = 0; c < 3; c++) {
        const v = (data[p + c] - a * 255) / (1 - a);
        data[p + c] = v < 0 ? 0 : v > 255 ? 255 : Math.round(v);
      }
    }
  }
}

// Last touch: on the thin line along the ✦ edge only, each pixel takes the
// middle value of its neighbours - wipes any leftover hair-line outline
// without blurring the rest of the photo.
function cleanEdges(data, W, fit) {
  const { n, alpha } = fit;
  let maxEdge = 0;
  const edge = new Float32Array(n * n);
  for (let y = 1; y < n - 1; y++) {
    for (let x = 1; x < n - 1; x++) {
      const i = y * n + x;
      edge[i] = Math.abs(alpha[i + 1] - alpha[i - 1]) + Math.abs(alpha[i + n] - alpha[i - n]);
      if (edge[i] > maxEdge) maxEdge = edge[i];
    }
  }
  if (maxEdge <= 0) return;
  const copy = new Uint8ClampedArray(data);
  const r = 2;
  const values = [[], [], []];
  for (let y = r; y < n - r; y++) {
    for (let x = r; x < n - r; x++) {
      if (edge[y * n + x] < maxEdge * 0.12) continue;
      values[0].length = values[1].length = values[2].length = 0;
      for (let dy = -r; dy <= r; dy++) {
        for (let dx = -r; dx <= r; dx++) {
          const q = ((fit.by + y + dy) * W + fit.bx + x + dx) * 4;
          values[0].push(copy[q]);
          values[1].push(copy[q + 1]);
          values[2].push(copy[q + 2]);
        }
      }
      const p = ((fit.by + y) * W + fit.bx + x) * 4;
      for (let c = 0; c < 3; c++) {
        values[c].sort((a, b) => a - b);
        data[p + c] = values[c][values[c].length >> 1];
      }
    }
  }
}

/**
 * Takes a loaded photo (ImageBitmap / <img> / canvas) at FULL size.
 * If it has the Gemini ✦, returns a new full-size canvas without it.
 * If not (or anything goes wrong), returns null - use the photo as is.
 */
export function removeGeminiMarkFromImage(source, W, H) {
  try {
    if (!W || !H || W < 200 || H < 200) return null;
    // Only the bottom-right corner is checked (fast on iPhone).
    const box = Math.min(W, H, Math.max(420, Math.round(Math.max(W, H) * 0.3)));
    const corner = document.createElement("canvas");
    corner.width = box;
    corner.height = box;
    const cctx = corner.getContext("2d", { willReadFrequently: true });
    cctx.drawImage(source, W - box, H - box, box, box, 0, 0, box, box);
    const img = cctx.getImageData(0, 0, box, box);
    const result = removeGeminiMarkFromPixels(img.data, box, box, W, H);
    if (!result.removed) return null;

    const full = document.createElement("canvas");
    full.width = W;
    full.height = H;
    const fctx = full.getContext("2d");
    fctx.drawImage(source, 0, 0);
    fctx.putImageData(img, W - box, H - box);
    return full;
  } catch (error) {
    console.warn("Gemini mark check skipped:", error);
    return null;
  }
}
